import base64, os

base_dir = os.path.join(os.path.dirname(__file__), '..', 'public')
os.makedirs(os.path.join(base_dir, 'builders'), exist_ok=True)
os.makedirs(os.path.join(base_dir, 'brands'), exist_ok=True)

logos = {
    # BUILDERS
    'builders/aparna.png': '',
}

for fname, b64 in logos.items():
    fpath = os.path.join(base_dir, fname)
    data = base64.b64decode(b64)
    with open(fpath, 'wb') as f:
        f.write(data)
    print(f"Saved {fpath} ({len(data)} bytes)")

print("All logos saved!")
